arguments.ioc_status:
{{ 'IndicatorStatus' | picklist('Blocked')
   if vars.input.params.ioc_blocked in [true, 'true', 'True', 1, '1']
   else 'IndicatorStatus' | picklist('TBD') }}

arguments.iocRecords:
{%- set ioclist = [] -%}
{%- for i in vars.steps.Create_IoCs -%}{%- if "Blocked" not in i.indicatorStatus.itemValue -%}
{%- set tmp = ioclist.append({"IRI":i['@id'],"Value": i.value , "Type":i.typeofindicator.itemValue})-%}{%-endif-%}{%-endfor-%}{{ioclist}}

arguments.file_iris:
{% set files = [] %}
{% for item in vars.steps.Get_the_Attachment %}
    {% set _ = files.append(item.file['@id']) %}
{% endfor %}
{{ files }}

arguments.total_iocs:
{% set ns = namespace(total_feeds=0) %}

{% for item in vars.steps.Extract_IoCs_From_File %}
    {% for indicator_type, indicators in item.data.items() %}
        {% set ns.total_feeds = ns.total_feeds + (indicators | length) %}
    {% endfor %}
{% endfor %}

{{ ns.total_feeds }}

arguments.fetched_indicators:
{% set ns = namespace(merged={}) %}

{% for item in vars.steps.Extract_IoCs_From_File | default([]) %}
    {% for indicator_type in item.data | default({}) %}
        {% set indicators = item.data[indicator_type] | default([]) %}

        {% if indicator_type not in ns.merged %}
            {% set _ = ns.merged.update({ indicator_type: [] }) %}
        {% endif %}

        {% for ioc in indicators %}
            {% if ioc not in ns.merged[indicator_type] %}
                {% set _ = ns.merged[indicator_type].append(ioc) %}
            {% endif %}
        {% endfor %}

    {% endfor %}
{% endfor %}

{{ ns.merged }}
